"""Sortie ZF2, batch 5: the conductor set through periodicity on units
(dchrcondper1/2), the gcd lemma (Mathlib factorsThrough_gcd), the conductor
divides every member (conductor_dvd_of_mem_conductorSet), membership iff
divisibility, invariance under inducing and under inversion."""
import sys, os; sys.path.insert(0, os.path.join(os.path.dirname(__file__), '..')); from tm import *
from zf2lib import *
only = sys.argv[1:]
def run(w):
    if only and w.label not in only: return True
    return w.run()

def dchr_hyps(w, n):
    return (w.s([], 'eqid', '( DChr ` %s ) = ( DChr ` %s )' % (n, n)),
            w.s([], 'eqid', '( Z/nZ ` %s ) = ( Z/nZ ` %s )' % (n, n)),
            w.s([], 'eqid', '%s = %s' % (DB(n), DB(n))),
            w.s([], 'eqid', '%s = %s' % (LZ(n), LZ(n))))
def lzf(w, ante, n0, lev):
    """( ante -> Llev : ZZ --> Blev ) from n0: ( ante -> lev e. NN0 )"""
    z = w.s([], 'eqid', '( Z/nZ ` %s ) = ( Z/nZ ` %s )' % (lev, lev)); b = w.s([], 'eqid', '%s = %s' % (BZ(lev), BZ(lev))); l = w.s([], 'eqid', '%s = %s' % (LZ(lev), LZ(lev)))
    fo = w.s([n0, w.s([z, b, l], 'znzrhfo', '( %s e. NN0 -> %s : ZZ -onto-> %s )' % (lev, LZ(lev), BZ(lev)))], 'syl', '( %s -> %s : ZZ -onto-> %s )' % (ante, LZ(lev), BZ(lev)))
    return w.s([fo, w.inst('fof')], 'syl', '( %s -> %s : ZZ --> %s )' % (ante, LZ(lev), BZ(lev)))
def znunit_st(w, ante, n0, az, lev, a):
    z = w.s([], 'eqid', '( Z/nZ ` %s ) = ( Z/nZ ` %s )' % (lev, lev)); u = w.s([], 'eqid', '%s = %s' % (UZ(lev), UZ(lev))); l = w.s([], 'eqid', '%s = %s' % (LZ(lev), LZ(lev)))
    return w.s([n0, az, w.s([z, u, l], 'znunit', '( ( %s e. NN0 /\\ %s e. ZZ ) -> ( ( %s ` %s ) e. %s <-> %s ) )' % (lev, a, LZ(lev), a, UZ(lev), COP(a, lev)))], 'syl2anc', '( %s -> ( ( %s ` %s ) e. %s <-> %s ) )' % (ante, LZ(lev), a, UZ(lev), COP(a, lev)))
def zndvds_st(w, ante, n0, az, bz, lev, a, b):
    z = w.s([], 'eqid', '( Z/nZ ` %s ) = ( Z/nZ ` %s )' % (lev, lev)); l = w.s([], 'eqid', '%s = %s' % (LZ(lev), LZ(lev)))
    return w.s([n0, az, bz, w.s([z, l], 'zndvds', '( ( %s e. NN0 /\\ %s e. ZZ /\\ %s e. ZZ ) -> ( ( %s ` %s ) = ( %s ` %s ) <-> %s || ( %s - %s ) ) )' % (lev, a, b, LZ(lev), a, LZ(lev), b, lev, a, b))], 'syl3anc', '( %s -> ( ( %s ` %s ) = ( %s ` %s ) <-> %s || ( %s - %s ) ) )' % (ante, LZ(lev), a, LZ(lev), b, lev, a, b))

HC = '( N e. NN /\\ X e. %s )' % DB('N')
C = COND('N', 'X'); CS = CSET('N', 'X')
def BODY(d, n, x): return '( %s || %s /\\ E. y e. %s %s = %s )' % (d, n, DB(d), x, IND(d, n, 'y'))

# ---- coprmliftn: the lifted integer can be taken positive
HCL = '( ( N e. NN /\\ M e. NN ) /\\ A e. ZZ /\\ ( A gcd N ) = 1 )'
SP = '{ q e. Prime | N || ( q - A ) }'
w = W('coprmliftn', 'Unit lifting with a positive witness: every integer A coprime to N is congruent mod N to a positive integer coprime to M (the prime of coprmlift).')
n = w.s([], 'simp1l', '( %s -> N e. NN )' % HCL); m = w.s([], 'simp1r', '( %s -> M e. NN )' % HCL); a = w.s([], 'simp2', '( %s -> A e. ZZ )' % HCL); c = w.s([], 'simp3', '( %s -> ( A gcd N ) = 1 )' % HCL)
SP0 = SP.replace('q e. Prime | N || ( q - A )', 'p e. Prime | N || ( p - A )')
di0 = w.s([n, a, c, w.inst('dirith')], 'syl3anc', '( %s -> %s ~~ NN )' % (HCL, SP0))
cbv = w.s([w.s([w.s([], 'oveq1', '( p = q -> ( p - A ) = ( q - A ) )')], 'breq2d', '( p = q -> ( N || ( p - A ) <-> N || ( q - A ) ) )')], 'cbvrabv', '%s = %s' % (SP0, SP))
di = w.s([cbv, di0], 'eqbrtrrid', '( %s -> %s ~~ NN )' % (HCL, SP))
en = w.s([di, w.inst('enfi')], 'syl', '( %s -> ( %s e. Fin <-> NN e. Fin ) )' % (HCL, SP))
nf = w.s([w.s([w.s([], 'nnnfi', '-. NN e. Fin')], 'a1i', '( %s -> -. NN e. Fin )' % HCL), en], 'mtbird', '( %s -> -. %s e. Fin )' % (HCL, SP))
ss = w.s([w.s([w.s([], 'ssrab2', '%s C_ Prime' % SP), w.s([], 'prmssnn', 'Prime C_ NN')], 'sstri', '%s C_ NN' % SP)], 'a1i', '( %s -> %s C_ NN )' % (HCL, SP))
ex = w.s([ss, nf, m, w.inst('coprmliftlem')], 'syl3anc', '( %s -> E. p e. %s M < p )' % (HCL, SP))
A2 = '( %s /\\ ( p e. %s /\\ M < p ) )' % (HCL, SP)
pm = w.s([], 'simprl', '( %s -> p e. %s )' % (A2, SP)); lt = w.s([], 'simprr', '( %s -> M < p )' % A2)
el = w.s([w.s([w.s([], 'oveq1', '( q = p -> ( q - A ) = ( p - A ) )')], 'breq2d', '( q = p -> ( N || ( q - A ) <-> N || ( p - A ) ) )')], 'elrab', '( p e. %s <-> ( p e. Prime /\\ N || ( p - A ) ) )' % SP)
pr = w.s([pm, el], 'sylib', '( %s -> ( p e. Prime /\\ N || ( p - A ) ) )' % A2)
pp = w.s([pr], 'simpld', '( %s -> p e. Prime )' % A2); dv = w.s([pr], 'simprd', '( %s -> N || ( p - A ) )' % A2)
pn = w.s([pp, w.s([], 'prmnn', '( p e. Prime -> p e. NN )')], 'syl', '( %s -> p e. NN )' % A2)
pz = w.s([pn], 'nnzd', '( %s -> p e. ZZ )' % A2)
m2 = w.s([m], 'adantr', '( %s -> M e. NN )' % A2)
dl = w.s([pz, m2, w.inst('dvdsle')], 'syl2anc', '( %s -> ( p || M -> p <_ M ) )' % A2)
nle = w.s([w.s([m2], 'nnred', '( %s -> M e. RR )' % A2), w.s([pn], 'nnred', '( %s -> p e. RR )' % A2), w.inst('ltnle')], 'syl2anc', '( %s -> ( M < p <-> -. p <_ M ) )' % A2)
nle2 = w.s([lt, nle], 'mpbid', '( %s -> -. p <_ M )' % A2)
nd = w.s([nle2, dl], 'mtod', '( %s -> -. p || M )' % A2)
cpb = w.s([pp, w.s([m2], 'nnzd', '( %s -> M e. ZZ )' % A2), w.inst('coprm')], 'syl2anc', '( %s -> ( -. p || M <-> ( p gcd M ) = 1 ) )' % A2)
cp = w.s([nd, cpb], 'mpbid', '( %s -> ( p gcd M ) = 1 )' % A2)
bo = w.s([dv, cp], 'jca', '( %s -> ( N || ( p - A ) /\\ ( p gcd M ) = 1 ) )' % A2)
s1 = w.s([], 'oveq1', '( b = p -> ( b - A ) = ( p - A ) )'); s2 = w.s([s1], 'breq2d', '( b = p -> ( N || ( b - A ) <-> N || ( p - A ) ) )')
s3 = w.s([], 'oveq1', '( b = p -> ( b gcd M ) = ( p gcd M ) )'); s4 = w.s([s3], 'eqeq1d', '( b = p -> ( ( b gcd M ) = 1 <-> ( p gcd M ) = 1 ) )')
s5 = w.s([s2, s4], 'anbi12d', '( b = p -> ( ( N || ( b - A ) /\\ ( b gcd M ) = 1 ) <-> ( N || ( p - A ) /\\ ( p gcd M ) = 1 ) ) )')
rs = w.s([pn, bo, w.s([s5], 'rspcev', '( ( p e. NN /\\ ( N || ( p - A ) /\\ ( p gcd M ) = 1 ) ) -> E. b e. NN ( N || ( b - A ) /\\ ( b gcd M ) = 1 ) )')], 'syl2anc', '( %s -> E. b e. NN ( N || ( b - A ) /\\ ( b gcd M ) = 1 ) )' % A2)
w.qed([ex, rs], 'rexlimddv', '( %s -> E. b e. NN ( N || ( b - A ) /\\ ( b gcd M ) = 1 ) )' % HCL); run(w)

# ---- dchrperlem: instantiating periodicity
HPL = '( %s /\\ ( A e. ZZ /\\ B e. ZZ ) /\\ ( ( %s /\\ %s ) /\\ D || ( A - B ) ) )' % (PER('D'), COP('A', 'N'), COP('B', 'N'))
w = W('dchrperlem', 'Lemma: instantiating the periodicity of X on the units mod D at two integers.')
i1 = w.s([], 'id', '( a = A -> a = A )')
c1, n1 = w.wcongr(PERAB('a', 'b', 'D'), {'a': 'A'}, 'a = A', {'a': i1}); assert n1 == PERAB('A', 'b', 'D'), n1
i2 = w.s([], 'id', '( b = B -> b = B )')
c2, n2 = w.wcongr(PERAB('A', 'b', 'D'), {'b': 'B'}, 'b = B', {'b': i2}); assert n2 == PERAB('A', 'B', 'D'), n2
r = w.s([c1, c2], 'rspc2va', '( ( ( A e. ZZ /\\ B e. ZZ ) /\\ %s ) -> %s )' % (PER('D'), PERAB('A', 'B', 'D')))
ab = w.s([], 'simp2', '( %s -> ( A e. ZZ /\\ B e. ZZ ) )' % HPL); pe = w.s([], 'simp1', '( %s -> %s )' % (HPL, PER('D')))
r2 = w.s([ab, pe, r], 'syl2anc', '( %s -> %s )' % (HPL, PERAB('A', 'B', 'D')))
w.qed([w.s([], 'simp3', '( %s -> ( ( %s /\\ %s ) /\\ D || ( A - B ) ) )' % (HPL, COP('A', 'N'), COP('B', 'N'))), r2], 'mpd', '( %s -> %s = %s )' % (HPL, EV('X', 'N', 'A'), EV('X', 'N', 'B'))); run(w)

# ---- dchrcondper1: a member of the conductor set gives periodicity
HP1 = '( %s /\\ D e. %s )' % (HC, CS)
w = W('dchrcondper1', 'A character induced from level D is periodic mod D on the integers coprime to N (one half of Mathlib factorsThrough_iff_ker_unitsMap).')
el = w.s([w.s([], 'simpr', '( %s -> D e. %s )' % (HP1, CS)), w.s([], 'dchrcondel', '( D e. %s <-> ( D e. NN /\\ %s ) )' % (CS, BODY('D', 'N', 'X')))], 'sylib', '( %s -> ( D e. NN /\\ %s ) )' % (HP1, BODY('D', 'N', 'X')))
dn = w.s([el], 'simpld', '( %s -> D e. NN )' % HP1); ddv = w.s([w.s([el], 'simprd', '( %s -> %s )' % (HP1, BODY('D', 'N', 'X')))], 'simpld', '( %s -> D || N )' % HP1)
ex = w.s([w.s([el], 'simprd', '( %s -> %s )' % (HP1, BODY('D', 'N', 'X')))], 'simprd', '( %s -> E. y e. %s X = %s )' % (HP1, DB('D'), IND('D', 'N', 'y')))
iz0 = w.s([], 'id', '( y = z -> y = z )'); cyz, nyz = w.wcongr('X = %s' % IND('D', 'N', 'y'), {'y': 'z'}, 'y = z', {'y': iz0})
ex = w.s([ex, w.s([cyz], 'cbvrexvw', '( E. y e. %s X = %s <-> E. z e. %s X = %s )' % (DB('D'), IND('D', 'N', 'y'), DB('D'), IND('D', 'N', 'z')))], 'sylib', '( %s -> E. z e. %s X = %s )' % (HP1, DB('D'), IND('D', 'N', 'z')))
A2 = '( %s /\\ ( z e. %s /\\ X = %s ) )' % (HP1, DB('D'), IND('D', 'N', 'z'))
A3 = '( %s /\\ ( a e. ZZ /\\ b e. ZZ ) )' % A2; A4 = '( %s /\\ ( ( %s /\\ %s ) /\\ D || ( a - b ) ) )' % (A3, COP('a', 'N'), COP('b', 'N'))
n4 = w.s([w.s([], 'simpl', '( %s -> N e. NN )' % HC)], 'ad4antr', '( %s -> N e. NN )' % A4); d4 = w.s([dn], 'ad3antrrr', '( %s -> D e. NN )' % A4); dv4 = w.s([ddv], 'ad3antrrr', '( %s -> D || N )' % A4)
y4 = w.s([], 'ad2antlr' if False else 'simpllr', '( %s -> ( z e. %s /\\ X = %s ) )' % (A4, DB('D'), IND('D', 'N', 'z')))
w.lines.pop()
y4 = w.s([w.s([], 'simpr', '( %s -> ( z e. %s /\\ X = %s ) )' % (A2, DB('D'), IND('D', 'N', 'z')))], 'ad2antrr', '( %s -> ( z e. %s /\\ X = %s ) )' % (A4, DB('D'), IND('D', 'N', 'z')))
yd = w.s([y4], 'simpld', '( %s -> z e. %s )' % (A4, DB('D'))); xe = w.s([y4], 'simprd', '( %s -> X = %s )' % (A4, IND('D', 'N', 'z')))
az = w.s([w.s([], 'simprl', '( %s -> a e. ZZ )' % A3)], 'adantr', '( %s -> a e. ZZ )' % A4); bz = w.s([w.s([], 'simprr', '( %s -> b e. ZZ )' % A3)], 'adantr', '( %s -> b e. ZZ )' % A4)
ca = w.s([w.s([], 'simprl', '( %s -> ( %s /\\ %s ) )' % (A4, COP('a', 'N'), COP('b', 'N')))], 'simpld', '( %s -> %s )' % (A4, COP('a', 'N')))
cb = w.s([w.s([], 'simprl', '( %s -> ( %s /\\ %s ) )' % (A4, COP('a', 'N'), COP('b', 'N')))], 'simprd', '( %s -> %s )' % (A4, COP('b', 'N')))
dab = w.s([], 'simprr', '( %s -> D || ( a - b ) )' % A4)
hx = w.s([w.s([d4, n4, dv4], '3jca', '( %s -> ( D e. NN /\\ N e. NN /\\ D || N ) )' % A4), yd], 'jca', '( %s -> ( ( D e. NN /\\ N e. NN /\\ D || N ) /\\ z e. %s ) )' % (A4, DB('D')))
v1 = w.s([hx, az, ca, w.inst('dchrindval1')], 'syl3anc', '( %s -> %s = %s )' % (A4, EV(IND('D', 'N', 'z'), 'N', 'a'), EV('z', 'D', 'a')))
v2 = w.s([hx, bz, cb, w.inst('dchrindval1')], 'syl3anc', '( %s -> %s = %s )' % (A4, EV(IND('D', 'N', 'z'), 'N', 'b'), EV('z', 'D', 'b')))
zd = zndvds_st(w, A4, w.s([d4], 'nnnn0d', '( %s -> D e. NN0 )' % A4), az, bz, 'D', 'a', 'b')
lab = w.s([dab, zd], 'mpbird', '( %s -> ( %s ` a ) = ( %s ` b ) )' % (A4, LZ('D'), LZ('D')))
v3 = w.s([lab], 'fveq2d', '( %s -> %s = %s )' % (A4, EV('z', 'D', 'a'), EV('z', 'D', 'b')))
v4 = w.s([v1, v3, v2], '3eqtr4d', '( %s -> %s = %s )' % (A4, EV(IND('D', 'N', 'z'), 'N', 'a'), EV(IND('D', 'N', 'z'), 'N', 'b')))
x1 = w.s([xe], 'fveq1d', '( %s -> %s = %s )' % (A4, EV('X', 'N', 'a'), EV(IND('D', 'N', 'z'), 'N', 'a'))); x2 = w.s([xe], 'fveq1d', '( %s -> %s = %s )' % (A4, EV('X', 'N', 'b'), EV(IND('D', 'N', 'z'), 'N', 'b')))
v5 = w.s([x1, v4, x2], '3eqtr4d', '( %s -> %s = %s )' % (A4, EV('X', 'N', 'a'), EV('X', 'N', 'b')))
v6 = w.s([v5], 'ex', '( %s -> %s )' % (A3, PERAB('a', 'b', 'D')))
v7 = w.s([v6], 'ralrimivva', '( %s -> %s )' % (A2, PER('D')))
w.qed([ex, v7], 'rexlimddv', '( %s -> %s )' % (HP1, PER('D'))); run(w)

# ---- dchrwitcl: the canonical positive witness of a unit class mod D coprime to N
HW = '( ( N e. NN /\\ D e. NN /\\ D || N ) /\\ K e. %s )' % UZ('D')
WK = WIT('D', 'N', 'K'); SKK = SK('D', 'N', 'K'); SKL = SK('D', 'N', 'K', 'l')
w = W('dchrwitcl', 'The witness of a unit class K mod D: the least positive integer in the class K that is coprime to N (nonempty by coprmliftn); it is positive, lies in the class K, and is coprime to N.')
n = w.s([w.s([], 'simpl', '( %s -> ( N e. NN /\\ D e. NN /\\ D || N ) )' % HW)], 'simp1d', '( %s -> N e. NN )' % HW)
d = w.s([w.s([], 'simpl', '( %s -> ( N e. NN /\\ D e. NN /\\ D || N ) )' % HW)], 'simp2d', '( %s -> D e. NN )' % HW)
ku = w.s([], 'simpr', '( %s -> K e. %s )' % (HW, UZ('D')))
b = w.s([], 'eqid', '%s = %s' % (BZ('D'), BZ('D'))); u = w.s([], 'eqid', '%s = %s' % (UZ('D'), UZ('D')))
kb = w.s([ku, w.s([b, u], 'unitcl', '( K e. %s -> K e. %s )' % (UZ('D'), BZ('D')))], 'syl', '( %s -> K e. %s )' % (HW, BZ('D')))
R = REP('D', 'K')
rz = w.s([d, kb, w.inst('dchrindlem1')], 'syl2anc', '( %s -> %s e. ZZ )' % (HW, R))
rk = w.s([d, kb, w.inst('dchrindlem2')], 'syl2anc', '( %s -> ( %s ` %s ) = K )' % (HW, LZ('D'), R))
d0 = w.s([d], 'nnnn0d', '( %s -> D e. NN0 )' % HW)
ru = w.s([rk, ku], 'eqeltrd', '( %s -> ( %s ` %s ) e. %s )' % (HW, LZ('D'), R, UZ('D')))
rc = w.s([ru, znunit_st(w, HW, d0, rz, 'D', R)], 'mpbid', '( %s -> %s )' % (HW, COP(R, 'D')))
lift = w.s([w.s([d, n], 'jca', '( %s -> ( D e. NN /\\ N e. NN ) )' % HW), rz, rc, w.inst('coprmliftn')], 'syl3anc', '( %s -> E. b e. NN ( D || ( b - %s ) /\\ %s ) )' % (HW, R, COP('b', 'N')))
A2 = '( %s /\\ ( b e. NN /\\ ( D || ( b - %s ) /\\ %s ) ) )' % (HW, R, COP('b', 'N'))
bn = w.s([], 'simprl', '( %s -> b e. NN )' % A2); bd = w.s([w.s([], 'simprr', '( %s -> ( D || ( b - %s ) /\\ %s ) )' % (A2, R, COP('b', 'N')))], 'simpld', '( %s -> D || ( b - %s ) )' % (A2, R))
bc = w.s([w.s([], 'simprr', '( %s -> ( D || ( b - %s ) /\\ %s ) )' % (A2, R, COP('b', 'N')))], 'simprd', '( %s -> %s )' % (A2, COP('b', 'N')))
zd = zndvds_st(w, A2, w.s([d0], 'adantr', '( %s -> D e. NN0 )' % A2), w.s([bn], 'nnzd', '( %s -> b e. ZZ )' % A2), w.s([rz], 'adantr', '( %s -> %s e. ZZ )' % (A2, R)), 'D', 'b', R)
lb = w.s([w.s([bd, zd], 'mpbird', '( %s -> ( %s ` b ) = ( %s ` %s ) )' % (A2, LZ('D'), LZ('D'), R)), w.s([rk], 'adantr', '( %s -> ( %s ` %s ) = K )' % (A2, LZ('D'), R))], 'eqtrd', '( %s -> ( %s ` b ) = K )' % (A2, LZ('D')))
ib = w.s([], 'id', '( c = b -> c = b )')
cb_, nb = w.wcongr('( ( %s ` c ) = K /\\ %s )' % (LZ('D'), COP('c', 'N')), {'c': 'b'}, 'c = b', {'c': ib})
mem = w.s([bn, w.s([lb, bc], 'jca', '( %s -> ( ( %s ` b ) = K /\\ %s ) )' % (A2, LZ('D'), COP('b', 'N'))), w.s([cb_], 'elrab', '( b e. %s <-> ( b e. NN /\\ ( ( %s ` b ) = K /\\ %s ) ) )' % (SKK, LZ('D'), COP('b', 'N')))], 'sylanbrc', '( %s -> b e. %s )' % (A2, SKK))
ne = w.s([mem, w.inst('ne0i')], 'syl', '( %s -> %s =/= (/) )' % (A2, SKK))
ne2 = w.s([lift, ne], 'rexlimddv', '( %s -> %s =/= (/) )' % (HW, SKK))
ss = w.s([w.s([w.s([], 'ssrab2', '%s C_ NN' % SKK), w.s([], 'nnuz', 'NN = ( ZZ>= ` 1 )')], 'sseqtri', '%s C_ ( ZZ>= ` 1 )' % SKK)], 'a1i', '( %s -> %s C_ ( ZZ>= ` 1 ) )' % (HW, SKK))
ic = w.s([ss, ne2, w.inst('infssuzcl')], 'syl2anc', '( %s -> %s e. %s )' % (HW, WK, SKK))
il = w.s([], 'id', '( c = l -> c = l )')
cl_, nl = w.wcongr('( ( %s ` c ) = K /\\ %s )' % (LZ('D'), COP('c', 'N')), {'c': 'l'}, 'c = l', {'c': il})
cbv = w.s([cl_], 'cbvrabv', '%s = %s' % (SKK, SKL))
ic2 = w.s([ic, cbv], 'eleqtrdi', '( %s -> %s e. %s )' % (HW, WK, SKL))
iw = w.s([], 'id', '( l = %s -> l = %s )' % (WK, WK))
cw, nw = w.wcongr('( ( %s ` l ) = K /\\ %s )' % (LZ('D'), COP('l', 'N')), {'l': WK}, 'l = %s' % WK, {'l': iw})
el = w.s([cw], 'elrab', '( %s e. %s <-> ( %s e. NN /\\ ( ( %s ` %s ) = K /\\ %s ) ) )' % (WK, SKL, WK, LZ('D'), WK, COP(WK, 'N')))
w.qed([ic2, el], 'sylib', '( %s -> ( %s e. NN /\\ ( ( %s ` %s ) = K /\\ %s ) ) )' % (HW, WK, LZ('D'), WK, COP(WK, 'N'))); run(w)

