w = W('dchrcondinv', 'The conductor of the inverse (conjugate) character equals the conductor of the character (Mathlib conductor_inv).')
n = w.s([], 'simpl', '( %s -> N e. NN )' % HC); x = w.s([], 'simpr', '( %s -> X e. %s )' % (HC, DB('N')))
ab = w.s([n, w.s([w.s([], 'eqid', '( DChr ` N ) = ( DChr ` N )')], 'dchrabl', '( N e. NN -> ( DChr ` N ) e. Abel )')], 'syl', '( %s -> ( DChr ` N ) e. Abel )' % HC)
