ixd = w.s([gr, x, w.s([bd, iv], 'grpinvcl', '( ( ( DChr ` N ) e. Grp /\\ X e. %s ) -> %s e. %s )' % (DB('N'), IX, DB('N')))], 'syl2anc', '( %s -> %s e. %s )' % (HC, IX, DB('N')))
le1 = w.s([], 'dchrcondinvle', '( %s -> %s <_ %s )' % (HC, CI, C))
IIX = '( %s ` %s )' % (INV('N'), IX)
