le2 = w.s([w.s([ii], 'oveq2d', '( %s -> %s = %s )' % (HC, COND('N', IIX), C)), le2a], 'eqbrtrrd', '( %s -> %s <_ %s )' % (HC, C, CI))
cn = w.s([], 'dchrcondnn', '( %s -> %s e. NN )' % (HC, C)); cin = w.s([n, ixd, w.inst('dchrcondnn')], 'syl2anc', '( %s -> %s e. NN )' % (HC, CI))
w.qed([w.s([le1, le2], 'jca', '( %s -> ( %s <_ %s /\\ %s <_ %s ) )' % (HC, CI, C, C, CI)), w.s([w.s([cin], 'nnred', '( %s -> %s e. RR )' % (HC, CI)), w.s([cn], 'nnred', '( %s -> %s e. RR )' % (HC, C)), w.inst('letri3')], 'syl2anc', '( %s -> ( %s = %s <-> ( %s <_ %s /\\ %s <_ %s ) ) )' % (HC, CI, C, CI, C, C, CI))], 'mpbird', '( %s -> %s = %s )' % (HC, CI, C)); run(w)
